import{_ as t,o as a,c as s,an as o}from"./chunks/framework.BhTTPPxl.js";const u=JSON.parse('{"title":"Data sources","description":"","frontmatter":{},"headers":[],"relativePath":"config/data_sources.md","filePath":"config/data_sources.md","lastUpdated":null}'),i={name:"config/data_sources.md"};function r(n,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="Data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#Data-sources" aria-label="Permalink to &quot;Data sources {#Data-sources}&quot;">​</a></h1><p>This page covers where to obtain the raw meteorological input the preprocessor needs, how to authenticate against each source, and the recommended local layout under <code>~/data/AtmosTransport/met/</code>.</p><p>If you only want to learn the runtime first, start with the <a href="/AtmosTransport.jl/dev/getting_started/quickstart#Quickstart">Quickstart</a>. It generates small current-format forcing locally and does not require a data account or a large download.</p><h2 id="ERA5-ECMWF-Reanalysis-5" tabindex="-1">ERA5 (ECMWF Reanalysis 5) <a class="header-anchor" href="#ERA5-ECMWF-Reanalysis-5" aria-label="Permalink to &quot;ERA5 (ECMWF Reanalysis 5) {#ERA5-ECMWF-Reanalysis-5}&quot;">​</a></h2><p>ERA5 supports LL, reduced-Gaussian and CS preprocessing. The repository has a unified downloader; choose its recipe together with a matching preprocessor. The older split spectral/thermo layout and the newer native N320 layout are not interchangeable merely by changing the input directory.</p><h3 id="Choose-a-download-route" tabindex="-1">Choose a download route <a class="header-anchor" href="#Choose-a-download-route" aria-label="Permalink to &quot;Choose a download route {#Choose-a-download-route}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Recipe</th><th style="text-align:right;">Local workflow</th></tr></thead><tbody><tr><td style="text-align:right;"><code>config/downloads/era5_arco.toml</code></td><td style="text-align:right;">Native core/surface downloads from the ARCO mirror. Pair with the ARCO-aware N320 source descriptor.</td></tr><tr><td style="text-align:right;"><code>config/downloads/era5_convection_only.toml</code></td><td style="text-align:right;">Additional CDS convection stream for a workflow that requires it.</td></tr><tr><td style="text-align:right;"><code>config/downloads/era5_native_daily.toml</code></td><td style="text-align:right;">CDS native model-level core, convection and surface streams, requested by day.</td></tr></tbody></table><p>Preview one day without downloading it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/downloads/download_data.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    config/downloads/era5_arco.toml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2021-12-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --end</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2021-12-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>Remove <code>--dry-run</code> to download after reviewing the output paths and requested streams. <code>config/met_sources/era5_n320_arco.toml</code> explicitly sources surface pressure from the downloaded single-level field because the assembled ARCO core lacks spectral <code>lnsp</code>. That descriptor currently disables optional surface/convection/diffusion payloads: downloading the surface files alone does not enable runtime physics. Read its comments and the <a href="/AtmosTransport.jl/dev/preprocessing/overview#Preprocessing-overview">preprocessing guide</a> before assembling a campaign.</p><p>CDS requests need credentials and accepted dataset terms; the public ARCO route does not use a CDS token. Check the selected recipe and its source descriptor for the exact file layout. Existing split-file spectral examples use the layout listed below instead of the native N320 bundle.</p><h3 id="Split-file-spectral-input" tabindex="-1">Split-file spectral input <a class="header-anchor" href="#Split-file-spectral-input" aria-label="Permalink to &quot;Split-file spectral input {#Split-file-spectral-input}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">File</th><th style="text-align:right;">Variable</th><th style="text-align:right;">Format</th></tr></thead><tbody><tr><td style="text-align:right;"><code>era5_spectral_YYYYMMDD_lnsp.gb</code></td><td style="text-align:right;">log surface pressure spectral coefficients</td><td style="text-align:right;">GRIB</td></tr><tr><td style="text-align:right;"><code>era5_spectral_YYYYMMDD_vo_d.gb</code></td><td style="text-align:right;">vorticity and divergence spectral coefficients</td><td style="text-align:right;">GRIB</td></tr><tr><td style="text-align:right;"><code>era5_thermo_ml_YYYYMMDD.nc</code></td><td style="text-align:right;">model-level specific humidity and temperature</td><td style="text-align:right;">NetCDF</td></tr></tbody></table><p>The thermo file supplies humidity for dry-air conversion. These examples use ERA5&#39;s 137 model levels, with surface pressure defining the hybrid coordinate. The files must already match the spectral reader&#39;s naming and variables; raw native bundles may require preparation rather than only renaming.</p><h3 id="Credentials" tabindex="-1">Credentials <a class="header-anchor" href="#Credentials" aria-label="Permalink to &quot;Credentials {#Credentials}&quot;">​</a></h3><p>Get a free CDS account, then drop your Personal Access Token (PAT) in <code>~/.cdsapirc</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>url: https://cds.climate.copernicus.eu/api</span></span>
<span class="line"><span>key: &lt;YOUR-PAT&gt;</span></span></code></pre></div><p>CDS migrated to single PAT-style keys in September 2024; the older <code>&lt;UID&gt;:&lt;API-KEY&gt;</code> format is no longer accepted. Get your PAT from your CDS account profile page once you&#39;re logged in. The <code>base_url</code> in <code>config/met_sources/era5.toml</code> matches this. Tools that read the CDS API will pick up the <code>~/.cdsapirc</code> file automatically.</p><h3 id="Datasets" tabindex="-1">Datasets <a class="header-anchor" href="#Datasets" aria-label="Permalink to &quot;Datasets {#Datasets}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">CDS dataset name</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;"><code>reanalysis-era5-complete</code></td><td style="text-align:right;">Model-level spectral fields (VO, D, LNSP) — the AtmosTransport spectral preprocessor input</td></tr><tr><td style="text-align:right;"><code>reanalysis-era5-single-levels</code></td><td style="text-align:right;">Surface fields (PS, 2T, 10U, 10V, …)</td></tr><tr><td style="text-align:right;"><code>reanalysis-era5-pressure-levels</code></td><td style="text-align:right;">Pressure-level diagnostics (not used by the preprocessor)</td></tr></tbody></table><p>The maintained downloader is <code>scripts/downloads/download_data.jl</code>; its recipes reference the descriptors in <code>config/met_sources/</code>. The native daily recipe includes the core and optional-physics request definitions.</p><h3 id="Recommended-local-layout" tabindex="-1">Recommended local layout <a class="header-anchor" href="#Recommended-local-layout" aria-label="Permalink to &quot;Recommended local layout {#Recommended-local-layout}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/data/AtmosTransport/met/era5/</span></span>
<span class="line"><span>└── 0.5x0.5/</span></span>
<span class="line"><span>    ├── spectral_hourly/                    # CDS reanalysis-era5-complete output</span></span>
<span class="line"><span>    │   ├── era5_spectral_20211201_lnsp.gb</span></span>
<span class="line"><span>    │   ├── era5_spectral_20211201_vo_d.gb</span></span>
<span class="line"><span>    │   └── …</span></span>
<span class="line"><span>    └── physics/</span></span>
<span class="line"><span>        └── era5_thermo_ml_20211201.nc      # CDS reanalysis-era5-complete with q</span></span></code></pre></div><p>The preprocessing <code>[input].spectral_dir</code> and <code>thermo_dir</code> keys point at these folders. They are not runtime <code>[input]</code> keys: the forward runtime consumes transport binaries. See <a href="/AtmosTransport.jl/dev/preprocessing/overview#Preprocessing-overview">Preprocessing overview</a>.</p><h2 id="GEOS-IT-NASA-GMAO-Integrated-Tropospheric" tabindex="-1">GEOS-IT (NASA GMAO Integrated Tropospheric) <a class="header-anchor" href="#GEOS-IT-NASA-GMAO-Integrated-Tropospheric" aria-label="Permalink to &quot;GEOS-IT (NASA GMAO Integrated Tropospheric) {#GEOS-IT-NASA-GMAO-Integrated-Tropospheric}&quot;">​</a></h2><p>GEOS-IT is the primary native cubed-sphere source. C180 (~50 km) is the production/debug resolution. GEOS-FP native C720 hourly CTM files are wired through the same source contract, with optional 0.25° surface/convection fallback files attached into the preprocessed binary.</p><h3 id="Per-day-file-set" tabindex="-1">Per-day file set <a class="header-anchor" href="#Per-day-file-set" aria-label="Permalink to &quot;Per-day file set {#Per-day-file-set}&quot;">​</a></h3><p>For each <code>YYYYMMDD</code>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">File</th><th style="text-align:right;">Cadence</th><th style="text-align:right;">Variables</th></tr></thead><tbody><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.CTM_A1.C180.nc</code></td><td style="text-align:right;">hourly (window-averaged)</td><td style="text-align:right;"><code>MFXC</code>, <code>MFYC</code>, <code>DELP</code></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.CTM_I1.C180.nc</code></td><td style="text-align:right;">hourly (instantaneous)</td><td style="text-align:right;"><code>PS</code>, <code>QV</code></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.A1.C180.nc</code></td><td style="text-align:right;">hourly</td><td style="text-align:right;"><code>PBLH</code>, <code>USTAR</code>, <code>HFLUX</code>, <code>T2M</code> <em>(only with <code>include_surface</code>)</em></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.A3mstE.C180.nc</code></td><td style="text-align:right;">3-hourly</td><td style="text-align:right;"><code>CMFMC</code> <em>(only with <code>include_convection</code>)</em></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.A3dyn.C180.nc</code></td><td style="text-align:right;">3-hourly</td><td style="text-align:right;"><code>DTRAIN</code> <em>(only with <code>include_convection</code>)</em>; <code>U</code>, <code>V</code> <em>(with <code>include_vdiff_fields</code>)</em></td></tr><tr><td style="text-align:right;"><code>GEOSIT.YYYYMMDD.I3.C180.nc</code></td><td style="text-align:right;">3-hourly</td><td style="text-align:right;"><code>T</code> <em>(only with <code>include_vdiff_fields</code>)</em></td></tr></tbody></table><p>The GCHP Holtslag-Boville VDIFF data contract additionally requires <code>include_vdiff_fields = true</code> in the preprocessing TOML and the <code>config/downloads/geosit_c180_gchp_vdiff.toml</code> download recipe.</p><p>The preprocessor needs <strong>next-day hour 0</strong> for the last window&#39;s forward-flux endpoint; download <code>[start, end+1]</code> for production runs.</p><h3 id="Access" tabindex="-1">Access <a class="header-anchor" href="#Access" aria-label="Permalink to &quot;Access {#Access}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Source</th><th style="text-align:right;">URL pattern</th><th style="text-align:right;">Auth</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>AWS S3 (primary)</strong> — <code>s3://geos-chem/GEOS_C180/GEOS_IT/...</code></td><td style="text-align:right;">public bucket; requester-pays NOT required</td><td style="text-align:right;">none — use <code>aws s3 cp --no-sign-request</code></td></tr><tr><td style="text-align:right;">WashU HTTP archive (fallback)</td><td style="text-align:right;"><code>http://geoschemdata.wustl.edu/ExtData/GEOS_C180/GEOS_IT/...</code></td><td style="text-align:right;">none</td></tr></tbody></table><p>The canonical descriptor is <code>config/met_sources/geosit.toml</code> (line 50-60), including the bucket name and the WashU base URL.</p><h3 id="Recommended-local-layout-2" tabindex="-1">Recommended local layout <a class="header-anchor" href="#Recommended-local-layout-2" aria-label="Permalink to &quot;Recommended local layout {#Recommended-local-layout-2}&quot;">​</a></h3><p>The downloader&#39;s canonical layout puts each day&#39;s collections under a per-day subdirectory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/data/AtmosTransport/met/geosit/</span></span>
<span class="line"><span>└── C180/</span></span>
<span class="line"><span>    └── daily/</span></span>
<span class="line"><span>        └── raw/</span></span>
<span class="line"><span>            └── 20211201/</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.CTM_A1.C180.nc</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.CTM_I1.C180.nc</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.A3mstE.C180.nc       # if convection</span></span>
<span class="line"><span>                ├── GEOSIT.20211201.A3dyn.C180.nc        # if convection or VDIFF</span></span>
<span class="line"><span>                └── GEOSIT.20211201.I3.C180.nc           # if GCHP VDIFF</span></span></code></pre></div><p>The <code>[source].root_dir</code> key in the GEOS preprocessing TOML points at the parent directory containing the <code>YYYYMMDD/</code> per-day folders (<code>~/data/AtmosTransport/met/geosit/C180/daily/raw</code> in this layout). The preprocessor&#39;s file resolver also accepts a flat directory of all NetCDFs (no per-day subdir) — that&#39;s the <code>raw_catrine</code> layout the project&#39;s own configs use historically.</p><h2 id="GEOS-FP,-MERRA-2-status" tabindex="-1">GEOS-FP, MERRA-2 (status) <a class="header-anchor" href="#GEOS-FP,-MERRA-2-status" aria-label="Permalink to &quot;GEOS-FP, MERRA-2 (status) {#GEOS-FP,-MERRA-2-status}&quot;">​</a></h2><p><strong>GEOS-FP (C720).</strong> The active descriptor is native cubed-sphere:</p><ul><li><p><code>config/met_sources/geosfp.toml</code> — the <strong>native C720 hourly CTM</strong> product (<code>GEOS.fp.asm.tavg_1hr_ctm_c0720_v72.*.nc4</code>).</p></li><li><p><code>config/downloads/geosfp_c720.toml</code> — the <strong>native C720</strong> cubed-sphere download descriptor; the <strong><code>src/Downloads/sources/geosfp.jl</code></strong> downloader pulls from the WashU HTTP archive (NOT the GEOS-IT-style AWS S3 path) into a local directory.</p></li></ul><p><code>GEOSSettings{:geosfp}</code> opens 24 hourly native CTM files plus the next-day 00Z endpoint. The WashU archive names the hourly averaged files with <code>HH30</code> timestamps; test fixtures may also use <code>HH00</code>. When <code>[source] include_surface = true</code> or <code>include_convection = true</code>, set <code>[source] physics_dir</code> to a directory containing <code>GEOSFP.YYYYMMDD.{A1,A3mstE,A3dyn}.025x03125.nc</code> files (or pre-regridded CS equivalents) and the preprocessor embeds <code>PBLH</code>, <code>USTAR</code>, <code>HFLUX</code>, <code>T2M</code>, <code>CMFMC</code>, and <code>DTRAIN</code> in the transport binary.</p><p><strong>MERRA-2.</strong> <code>MERRA2Settings</code> and the wind-derived CS writer are implemented. They read native 0.5° × 0.625° PS/QV/U/V fields, derive mass fluxes, and write CS transport binaries through the canonical preprocessing CLI; see <code>config/preprocessing/merra2_c180_dec2021_f32.toml</code>. MERRA-2 has no native MFXC/MFYC, so this is deliberately separate from <code>AbstractGEOSSettings</code>. The unified <code>OPeNDAPProtocol.execute!</code> downloader is still unavailable, so raw files must currently be staged separately with NASA Earthdata credentials.</p><h2 id="Try-the-runtime-without-external-data" tabindex="-1">Try the runtime without external data <a class="header-anchor" href="#Try-the-runtime-without-external-data" aria-label="Permalink to &quot;Try the runtime without external data {#Try-the-runtime-without-external-data}&quot;">​</a></h2><p>The maintained quickstart creates a small, deterministic version-4 transport binary in the repository&#39;s ignored <code>data/quickstart/</code> directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/generate_synthetic_quickstart.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run_transport.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/examples/minimal_template.toml</span></span></code></pre></div><p>This is the supported smoke test and tutorial path.</p><h2 id="A-note-on-disk-space" tabindex="-1">A note on disk space <a class="header-anchor" href="#A-note-on-disk-space" aria-label="Permalink to &quot;A note on disk space {#A-note-on-disk-space}&quot;">​</a></h2><p>Binary size scales with grid cells, vertical levels, windows, precision, and optional physics sections. Generate one representative day, inspect its <code>payload_sections</code>, and size campaign storage from that file rather than from a different source or physics configuration.</p><h2 id="Where-to-read-next" tabindex="-1">Where to read next <a class="header-anchor" href="#Where-to-read-next" aria-label="Permalink to &quot;Where to read next {#Where-to-read-next}&quot;">​</a></h2><ul><li><p><a href="/AtmosTransport.jl/dev/getting_started/quickstart#Quickstart">Quickstart</a> — a zero-download, runnable walkthrough.</p></li><li><p><a href="/AtmosTransport.jl/dev/config/toml_schema#TOML-schema">TOML schema</a> — runtime input and operator configuration.</p></li><li><p><a href="/AtmosTransport.jl/dev/preprocessing/overview#Preprocessing-overview">Preprocessing overview</a> — the unified <code>process_day</code> dispatch.</p></li></ul>`,51)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
